(function(root){'use strict';
const own=(x,k)=>Object.hasOwn(x,k),keys=(o,ks)=>o&&typeof o==='object'&&!Array.isArray(o)&&Object.keys(o).sort().join(',')===ks.slice().sort().join(',');
function text(v,max=500){if(typeof v!=='string'||!v.trim()||v.length>max||/[\u0000-\u001f]/.test(v))throw Error('Enter nonblank text within the stated limit, without control characters.');return v;}
function date(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v)||v<'1900-01-01'||v>'2200-12-31')throw Error('Use real dates from1900 through2200.');const d=new Date(v+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)throw Error('Enter a real calendar date.');return v;}
function num(v,type='money'){const cap=type==='hours'?10080:1000000;if(typeof v!=='string'||!/^\d{1,7}(\.\d{1,2})?$/.test(v)||Number(v)>cap)throw Error('Enter every amount, including zero, within its stated range; at most2 decimals, no commas.');return Math.round(Number(v)*100);}
function validate(c,x){const ks=['name','start','end','asof','notes',...c.fields.map(f=>f[0]),...(c.rows?['rows']:[])];if(!keys(x,ks))throw Error('Inputs do not match this tool.');text(x.name,100);text(x.notes,1000);date(x.start);date(x.end);date(x.asof);if(x.start>x.end||x.asof<x.start||x.asof>x.end)throw Error('Review date must be within the stated period.');let v={};for(const [k]of c.fields){if(k==='months'){if(typeof x[k]!=='string'||!/^\d{1,3}$/.test(x[k])||Number(x[k])<1||Number(x[k])>120)throw Error('Comparison months must be a whole number from1 to120.');v[k]=Number(x[k]);}else v[k]=num(x[k]);}
if(c.rows){if(!Array.isArray(x.rows)||x.rows.length<1||x.rows.length>30)throw Error('Enter1–30 cost lines or distinct roles.');const seen=new Set();v.rows=x.rows.map(row=>{if(!keys(row,c.rows.map(r=>r[0])))throw Error('Unexpected row fields.');let out={};for(const [k,l,t]of c.rows){if(t==='text'){out[k]=text(row[k],100);const label=out[k].trim().toLowerCase();if(seen.has(label))throw Error('Use distinct cost-line or role labels to avoid duplicate entries.');seen.add(label);}else if(t==='date'){out[k]=date(row[k]);if(out[k]<x.start||out[k]>x.asof)throw Error('Cost-line review dates must be within the period and on/before review date.');}else out[k]=num(row[k],t);}return out;});}return v;}
function calculate(c,x){const v=validate(c,x);let report=[],rows=[];if(c.mode==='benefit'){const ca=v.setupA+v.months*v.monthlyA,cb=v.setupB+v.months*v.monthlyB,ba=v.months*v.benefitA,bb=v.months*v.benefitB;report=[['A total cost',ca],['A total entered benefit',ba],['A net benefit',ba-ca],['B total cost',cb],['B total entered benefit',bb],['B net benefit',bb-cb],['A minus B net benefit',(ba-ca)-(bb-cb)]];}else if(c.mode==='project'){let a=0,b=0,f=0;rows=v.rows.map(r=>{a+=r.actual;b+=r.committed;f+=r.forecast;return [r.label,r.date,r.actual,r.committed,r.forecast,r.actual+r.committed+r.forecast];});report=[['Actual cost',a],['Remaining committed',b],['Other forecast',f],['Expected total cost',a+b+f],['Budget headroom',v.budget-a-b-f]];}else if(c.mode==='staff'){let req=0,av=0,gap=0,spare=0;rows=v.rows.map(r=>{req+=r.required;av+=r.available;const b=r.available-r.required;gap+=Math.max(0,-b);spare+=Math.max(0,b);return [r.label,r.required,r.available,b];});report=[['Total required hours',req],['Total available hours',av],['Overall hours balance',av-req],['Role shortages (not offset by other roles)',gap],['Role spare hours',spare]];}else throw Error('Unsupported tool.');if(report.some(r=>!Number.isSafeInteger(r[1])))throw Error('Amount exceeds supported precision.');return {report,rows,unit:c.mode==='staff'?'hours':'USD'};}
function csv(rows){return rows.map(r=>r.map(v=>{let s=String(v);if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
const api={validate,calculate,csv};if(typeof module==='object'&&module.exports)module.exports=api;if(!root.document)return;const d=root.document,el=id=>d.getElementById(id),cfg=el('bp-config');if(!cfg)return;const c=JSON.parse(cfg.textContent),form=el('bp-form'),status=el('bp-status'),out=el('bp-result');let reviewed=null,pending=null;const base=['name','start','end','asof','notes',...c.fields.map(f=>f[0])];
const heads=c.mode==='project'?['Cost line','Review date','Actual USD','Remaining committed USD','Other forecast USD','Expected total USD']:['Role','Required hours','Available hours','Balance hours'];
function invalidate(){reviewed=null;out.replaceChildren();el('bp-csv').disabled=el('bp-print').disabled=true;status.textContent='Entries changed. Review again before exporting.';}
function addRow(data={}){if(el('bp-rows').children.length>=30){status.textContent='Maximum30 rows.';return;}const fieldset=d.createElement('fieldset'),legend=d.createElement('legend');legend.textContent=c.mode==='project'?'Project cost line':'Role capacity';fieldset.append(legend);for(const [key,label,type]of c.rows){const lab=d.createElement('label');lab.textContent=label;const input=d.createElement('input');input.name=key;input.type=type==='date'?'date':'text';input.required=true;input.maxLength=type==='text'?100:12;if(type==='date'){input.min='1900-01-01';input.max='2200-12-31';}else if(type!=='text')input.inputMode='decimal';input.value=data[key]??'';lab.append(input);fieldset.append(lab);}const b=d.createElement('button');b.type='button';b.textContent='Remove row';b.addEventListener('click',()=>{fieldset.remove();invalidate();});fieldset.append(b);el('bp-rows').append(fieldset);}
function read(){let x=Object.fromEntries(base.map(k=>[k,el('bp-'+k).value]));if(c.rows)x.rows=Array.from(el('bp-rows').children).map(row=>Object.fromEntries(c.rows.map(([k])=>[k,row.querySelector('[name="'+k+'"]').value])));return x;}
function fill(x){base.forEach(k=>el('bp-'+k).value=x[k]);if(c.rows){el('bp-rows').replaceChildren();x.rows.forEach(addRow);}invalidate();}
function request(x,message){pending=x;el('bp-dialog-text').textContent=message;el('bp-dialog').showModal();}
function download(data,suffix,type){const u=URL.createObjectURL(new Blob([data],{type})),a=d.createElement('a');a.href=u;a.download=c.slug+suffix;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const fmt=(v,unit)=>unit==='hours'?(v/100).toFixed(2)+' hours':(v/100).toLocaleString('en-US',{style:'currency',currency:'USD'});
function table(headers,rows){const wrap=d.createElement('div');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Reviewed worksheet table');const t=d.createElement('table'),cap=d.createElement('caption');cap.textContent=c.mode==='staff'?'Fixed-period role capacity':'Reviewed cost comparison';t.append(cap);const thd=d.createElement('thead'),tr=d.createElement('tr');for(const s of headers){const th=d.createElement('th');th.scope='col';th.textContent=s;tr.append(th);}thd.append(tr);t.append(thd);const body=d.createElement('tbody');for(const r of rows){const tr=d.createElement('tr');r.forEach(v=>{const td=d.createElement('td');td.textContent=v;tr.append(td);});body.append(tr);}t.append(body);wrap.append(t);out.append(wrap);}
form.addEventListener('input',invalidate);form.addEventListener('change',invalidate);form.addEventListener('submit',e=>{e.preventDefault();try{const input=read(),result=calculate(c,input);out.replaceChildren();for(const value of [input.name,input.start+' to '+input.end+'; reviewed '+input.asof,'Assumptions: '+input.notes,c.scope]){const p=d.createElement('p');p.textContent=value;out.append(p);}table(['Measure','Result'],result.report.map(([label,v])=>[label,fmt(v,result.unit)]));if(result.rows.length)table(heads,result.rows.map(r=>r.map(v=>typeof v==='number'?fmt(v,result.unit):v)));reviewed={input,result};el('bp-csv').disabled=el('bp-print').disabled=false;status.textContent='Reviewed. Check completeness and source evidence; this report does not authorize a commitment.';}catch(e){invalidate();status.textContent=e.message;}});
if(c.rows){addRow();el('bp-add').addEventListener('click',()=>{addRow();invalidate();});}
el('bp-sample').addEventListener('click',()=>{const x={name:'Fictional '+c.slug,start:'2026-11-01',end:'2026-11-30',asof:'2026-11-19',notes:'Fictional educational example; fixed period and stated exclusions. '+c.scope,...Object.fromEntries(c.fields.map(([k,l,v])=>[k,v]))};if(c.rows)x.rows=c.sampleRows;request(x,'Replace current entries with the fictional example?');});
el('bp-clear').addEventListener('click',()=>{const x=Object.fromEntries(base.map(k=>[k,'']));if(c.rows)x.rows=[Object.fromEntries(c.rows.map(([k])=>[k,'']))];request(x,'Clear entries? Keep a JSON backup first if needed.');});
el('bp-cancel').addEventListener('click',()=>{pending=null;el('bp-dialog').close();});el('bp-confirm').addEventListener('click',()=>{if(pending)fill(pending);pending=null;el('bp-dialog').close();});el('bp-dialog').addEventListener('cancel',()=>{pending=null;});
el('bp-backup').addEventListener('click',()=>{try{const input=read();validate(c,input);download(JSON.stringify({tool:c.slug,version:1,input},null,2),'.json','application/json');status.textContent='Valid editable input backup downloaded; retain the source evidence separately.';}catch(e){status.textContent=e.message;}});
el('bp-import').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>65536)throw Error('Backup exceeds64 KB.');const b=JSON.parse(await f.text());if(!keys(b,['tool','version','input'])||b.tool!==c.slug||b.version!==1)throw Error('Choose a version-1 backup from this exact tool.');validate(c,b.input);request(b.input,'Replace current entries with the validated backup?');}catch(err){status.textContent='Import rejected: '+err.message;}finally{e.target.value='';}});
el('bp-csv').addEventListener('click',()=>{if(!reviewed)return;const {input,result}=reviewed;const rows=[['Worksheet',c.title],...base.map(k=>[k,input[k]]),['Unit',result.unit],['Scope',c.scope],['Measure','Result'],...result.report.map(([l,v])=>[l,(v/100).toFixed(2)]),...(result.rows.length?[heads,...result.rows.map(r=>r.map(v=>typeof v==='number'?(v/100).toFixed(2):v))]:[])];download('\uFEFF'+csv(rows),'-reviewed.csv','text/csv;charset=utf-8');});el('bp-print').addEventListener('click',()=>{if(reviewed)root.print();});
})(typeof window!=='undefined'?window:globalThis);
